contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_value)); require(_value <= 1000000000000000000000000000000);
        require(address(this).balance >= _value);

        uint256 valueBefore = c.value(); if (__ESBMC_reverted()) return;
        uint256 remainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;

        c.getTokens{value: _value}(); if (__ESBMC_reverted()) return;

        uint256 valueAfter = c.value(); if (__ESBMC_reverted()) return;

        uint256 effective = valueBefore;
        if (effective > remainingBefore) {
            effective = remainingBefore;
        }

        assert(valueAfter == (effective / 100000) * 99999);
    }

    receive() external payable {}
}

