pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 _value) internal {
        _value = bound(_value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        uint256 valueBefore;
        try c.value() returns (uint256 __r) { valueBefore = __r; } catch { return; }
        uint256 remainingBefore;
        try c.totalRemaining() returns (uint256 __r) { remainingBefore = __r; } catch { return; }
        try c.getTokens{value: _value}() {} catch { return; }
        uint256 valueAfter;
        try c.value() returns (uint256 __r) { valueAfter = __r; } catch { return; }
        uint256 effective = valueBefore;
        if (effective > remainingBefore) {
            effective = remainingBefore;
        }
        assertTrue(valueAfter == (effective / 100000) * 99999);
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
